// Text Encoding Exception: exact Vietnamese UI selectors in an independent Local probe.
import { afterEach, beforeEach, expect, it, vi } from 'vitest';
import { act, cleanup, fireEvent, render, screen } from '@testing-library/react';
import { SpecExport } from './SpecExport';
import type { Template } from '@/types';

vi.mock('@/lib/i18n', () => ({ useLanguage: () => ({ language: 'en', t: (key: string) => key }) }));
vi.mock('./Settings', () => ({ useSettings: () => ({ settings: { preferences: { defaultExportMode: 'simple' } }, isLoaded: true }) }));
vi.mock('./UserContext', () => ({ useUserContext: () => ({ getContextPrompt: () => '' }) }));
vi.mock('./WorkflowVisualizer', () => ({ WorkflowVisualizer: () => null }));
// Fixed leaves render an unrelated send affordance; no governance behavior asserted.
vi.mock('@/lib/enforcement', () => ({ evaluateEnforcement: () => ({ status: 'ALLOW', reasons: [] }) }));
vi.mock('@/lib/enforcement-log', () => ({ logEnforcementDecision: () => undefined }));

const template: Template = { id: 'local-copy-order', name: 'Local copy', icon: 'L', category: 'business',
    difficulty: 'easy', description: 'Synthetic clipboard presentation probe', intentPattern: 'Describe [goal]',
    outputExpected: ['Brief'], fields: [{ id: 'goal', type: 'text', label: 'Goal', placeholder: 'Goal', required: true }] };
const deferred = () => { let resolve!: () => void; let reject!: (reason: Error) => void;
    const promise = new Promise<void>((yes, no) => { resolve = yes; reject = no; }); return { promise, resolve, reject }; };
const clipboard = vi.fn();
beforeEach(() => {
    clipboard.mockReset();
    Object.defineProperty(navigator, 'clipboard', { configurable: true, value: { writeText: clipboard } });
    Object.defineProperty(URL, 'createObjectURL', { configurable: true, value: vi.fn(() => 'blob:local-copy') });
    Object.defineProperty(URL, 'revokeObjectURL', { configurable: true, value: vi.fn() });
    vi.spyOn(HTMLAnchorElement.prototype, 'click').mockImplementation(() => {});
    vi.stubGlobal('fetch', vi.fn(() => { throw new Error('All network denied by Local UI probe'); }));
});
afterEach(() => { cleanup(); vi.restoreAllMocks(); vi.unstubAllGlobals(); });
it('keeps the latest same-packet copy success when an older copy rejects late', async () => {
    const first = deferred(), second = deferred();
    clipboard.mockReturnValueOnce(first.promise).mockReturnValueOnce(second.promise);
    render(<SpecExport template={template} values={{ goal: 'LOCAL_COPY_ORDER_MARKER' }} />);
    fireEvent.click(screen.getByRole('button', { name: 'Xác nhận ý tưởng và xuất cho agent' }));
    fireEvent.click(screen.getByRole('button', { name: 'Sao chép Working Brief' }));
    fireEvent.click(screen.getByRole('button', { name: 'Sao chép Working Brief' }));
    expect(clipboard).toHaveBeenCalledTimes(2);
    expect(clipboard.mock.calls[0][0]).toBe(clipboard.mock.calls[1][0]);
    expect(clipboard.mock.calls[0][0]).toContain('LOCAL_COPY_ORDER_MARKER');
    await act(async () => second.resolve());
    expect(screen.getByRole('button', { name: 'Đã sao chép!' })).toBeTruthy();
    await act(async () => first.reject(new Error('OLDER_COPY_FAILED')));
    expect(screen.queryByRole('alert')).toBeNull();
    expect(screen.getByRole('button', { name: 'Đã sao chép!' })).toBeTruthy();
});
